import { $ } from "@hey-api/openapi-ts";
import { definePluginConfig } from "../../plugin.js";
import { inferEventType } from "../event-type.js";
import type { TypescriptApi } from "../typescript/types.js";

import { defaultConfig } from "./config.js";
import type { EventMapPluginConfig, EventMapResolvedConfig } from "./types.js";

const HEADER =
  "// AUTO-GENERATED by @ir-kit/asyncapi-typescript — do not hand-edit.";

/**
 * `isMessageOfType` narrows with a type predicate (`msg is EventMap[K]`),
 * which the `$` DSL can't build, so it is written as a plain string.
 */
const IS_MESSAGE_OF_TYPE = `export function isMessageOfType<K extends keyof EventMap>(msg: AnyMessage, type: K): msg is EventMap[K] {
  return (msg as { type?: string } | null | undefined)?.type === type;
}`;

export const eventMap = definePluginConfig<
  "event-map",
  EventMapPluginConfig,
  EventMapResolvedConfig,
  unknown
>({
  name: "event-map",
  defaultConfig,
  dependsOn: ["typescript"],
  handler(plugin) {
    const eventMap = $.type.object();
    const importNames = new Set<string>();

    const types = plugin.getApi<TypescriptApi>("typescript");

    for (const ev of plugin.forEach("message")) {
      if (ev.type !== "message") continue;
      const typeName = types?.messageTypeName(ev.message.id());
      if (typeName) importNames.add(typeName);
      eventMap.prop(inferEventType(ev.message), (p) =>
        p.type($.type(typeName ?? "unknown")),
      );
    }

    plugin.emitTs(
      "event-map.gen.ts",
      [
        $.type.alias("EventMap").export().type(eventMap),
        $.type
          .alias("AnyMessage")
          .export()
          .type(
            $.type.idx(
              $.type("EventMap"),
              $.type.operator().keyof($.type("EventMap")),
            ),
          ),
        IS_MESSAGE_OF_TYPE,
      ],
      {
        header: HEADER,
        imports: [
          {
            from: "types.gen",
            isType: true,
            names: Array.from(importNames)
              .sort()
              .map((name) => ({ name })),
          },
        ],
      },
    );
  },
});
